def replace_function(module, name, old, new):
    source = inspect.getsource(getattr(module, name))
    if source.count(old) != 1:
        raise RuntimeError("Fault target did not match exactly once: " + fault)
    namespace = dict(vars(module))
    exec(compile(source.replace(old, new), "<reuse-policy-fault:" + fault + ">", "exec"), namespace)
    setattr(module, name, namespace[name])

