def unauthenticated_normalization(recorded, verified, metadata, expected):
    ignored = {"observation_job_id", "observation_attempt", "carried_forward"}

    def identities(rows):
        return sorted(({key: value for key, value in row.items() if key not in ignored} for row in rows),
            key=lambda row: row.get("lane", ""))

    return identities(recorded) == identities(verified)

reuse._same_executions = unauthenticated_normalization
